# ── example numbers (computed, never typed by hand) ──
f1 = K9 * 2e-6 * 3e-6 / 0.3**2                       # 0.6 N
x_null = 30 * 2 / 3                                    # √4 = 2 → x/(30−x) = 2
p3 = 2e-6 * 0.02; tau3 = p3 * 5e5 * math.sin(math.radians(30)); w3 = 2 * p3 * 5e5
q4 = 1.77e-6; phi4 = q4 / e0; face4 = phi4 / 6
v5c = K9 * 1e-9 / 0.1; v5o = K9 * 1e-9 / 0.2
c6 = 3 * 6 / (3 + 6) + 4; q6 = c6 * 12; u6 = 0.5 * c6 * 144     # μF, μC, μJ
u7a = 0.5 * 10e-12 * 100**2; u7b = u7a / 5
v8 = 2 * 100 / (2 + 3); ui8 = 0.5 * 2e-6 * 100**2; uf8 = 0.5 * 5e-6 * v8**2
v9 = math.sqrt(2 * 100 * e / me)

